if (!form) return;
var inr = function (n) {
  var s = String(Math.round(n)), head = s.slice(0, -3), tail = s.slice(-3);
  return "₹" + (head ? head.replace(/\B(?=(\d\d)+(?!\d))/g, ",") + "," + tail : tail);
};
var rows = Array.prototype.slice.call(form.querySelectorAll(".item"));
var basket = document.getElementById("basket"), totalRow = document.getElementById("total-row");
var sums = document.getElementById("sums"), feeRow = document.getElementById("fee-row"), payNow = document.getElementById("pay-now");
var deliveryBox = document.getElementById("delivery-fields");
var d = form.dataset, baseFee = parseInt(d.fee, 10) || 0, freeAbove = parseInt(d.freeAbove, 10) || 0, advance = parseInt(d.advance, 10) || 0;
function wantsDelivery() {
  var r = form.querySelector('input[name="fulfilment"]:checked');
  if (r) return r.value === "delivery";
  var h = form.querySelector('input[type="hidden"][name="fulfilment"]');
  return !!h && h.value === "delivery";
}
function feeFor(items) {
  if (!wantsDelivery() || items <= 0) return 0;
  return freeAbove && items >= freeAbove ? 0 : baseFee;
}
var bar = document.getElementById("bar-order");
/* S21: an item has one quantity box (.q), or one per size / pack (qty_<i>_<j>); a sold-out item has none. */
function val(input) { var n = parseInt(input.value, 10), top = parseInt(input.max, 10) || 50; return isNaN(n) || n < 0 ? 0 : Math.min(n, top); }
function units(row) { return Array.prototype.slice.call(row.querySelectorAll(".q")); }
function rowSum(row) { return units(row).reduce(function (a, q) { return a + val(q.querySelector("input")); }, 0); }
function refresh() {
  var count = 0, total = 0, lines = [];
  rows.forEach(function (row) {
    var sum = 0, sel = row.querySelector(".choice select"), pick = sel && sel.value ? " · " + sel.value : "";
    units(row).forEach(function (q) {
      var input = q.querySelector("input"), n = val(input);
      q.classList.toggle("chosen", n > 0);
      q.querySelector("output").textContent = n;
      sum += n;
      if (n > 0) {
        count += n; total += n * Number(input.dataset.price);
        var li = document.createElement("li"), a = document.createElement("span"), b = document.createElement("span");
        a.textContent = n + " × " + input.dataset.name + pick; b.textContent = inr(n * Number(input.dataset.price));
        li.appendChild(a); li.appendChild(b); lines.push(li);
      }
    });
    row.classList.toggle("chosen", sum > 0);
    if (sel) sel.required = sum > 0;
  });
  basket.innerHTML = "";
  if (lines.length) { lines.forEach(function (li) { basket.appendChild(li); }); }
  else { var e = document.createElement("li"); e.className = "empty"; e.textContent = "Add items from the menu."; basket.appendChild(e); }
  var fee = feeFor(total), grand = total + fee;
  totalRow.hidden = !count;
  sums.hidden = !count || !wantsDelivery() || !(fee || baseFee);
  feeRow.hidden = sums.hidden;
  document.getElementById("items-sum").textContent = inr(total);
  document.getElementById("fee").textContent = fee ? inr(fee) : "Free";
  document.getElementById("total").textContent = inr(grand);
  var now = d.terms === "upfront" ? grand : d.terms === "advance" ? Math.min(grand, Math.max(1, Math.ceil(grand * advance / 100))) : 0;
  payNow.hidden = !count || !now;
  payNow.textContent = now ? "You'll pay " + inr(now) + " after you send the order" + (now < grand ? ", and " + inr(grand - now) + " later." : ".") : "";

