  await p.fill(`#custom_${i}`, 'Happy Birthday Riya (live demo check)');
  await p.setInputFiles('#reference_photo', path.resolve(process.argv[2]));
  await p.fill('#customer_name', 'Demo Check'); await p.fill('#customer_phone', '98765 43210');
  const d = p.locator('#wanted_date'); if (await d.count()) { const min = await d.getAttribute('min'); const t = new Date(min + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + 3); if (t.getUTCDay() === 2) t.setUTCDate(t.getUTCDate() + 1); await d.fill(t.toISOString().slice(0, 10)); }
  await p.locator('#order-form').evaluate(f => f.requestSubmit()); await p.waitForLoadState('load');
  const txt = await p.locator('main').innerText(); console.log(txt.includes('This is a demo'), txt.includes('Your request: Happy Birthday Riya'), txt.includes('checked and thrown away'));
  console.log('errors', JSON.stringify(errs)); await b.close(); })();
EOF
